from __future__ import annotations; from common.platform import generate_api_reference as gar; from common.platform import generate_openapi_spec as gen
def test_render_openapi_reference_uses_openapi_shape() -> None: 'AC8.13.53'; schema = {'info': {'title': 'Demo API', 'version': '1.2.3'}, 'paths': {'/journal-entries': {'get': {'tags': ['journal-entries'], 'summary': 'List Journal Entries', 'security': [{'OAuth2PasswordBearer': []}], 'parameters': [{'name': 'status_filter', 'in': 'query', 'required': False, 'schema': {'type': 'string'}}], 'responses': {'200': {'content': {'application/json': {'schema': {'$ref': '#/components/schemas/JournalEntryList'}}}}}}}, '/reconciliation/runs': {'post': {'tags': ['reconciliation'], 'summary': 'Run Reconciliation', 'security': [], 'requestBody': {'content': {'application/json': {'schema': {'$ref': '#/components/schemas/ReconciliationRunRequest'}}}}, 'responses': {'200': {'content': {}}, '404': {'content': {'application/json': {'schema': {'type': 'object'}}}}}}}, '/schemas': {'get': {'tags': ['untagged'], 'summary': 'Schema Samples', 'responses': {'200': {'content': {'application/json': {'schema': {'items': {'anyOf': [{'$ref': '#/components/schemas/A'}, {'allOf': [{'type': 'string'}, {'enum': ['x']}]}]}}}}}}}}}, 'components': {'schemas': {'JournalEntryList': {}, 'ReconciliationRunRequest': {}}}}; rendered = gar.render_openapi_reference(schema); assert 'API title: `Demo API`' in rendered; assert '| `GET` | `/journal-entries` | yes | `status_filter` (query)' in rendered; assert '`ReconciliationRunRequest`' in rendered; assert 'array[`A` \\| string + enum]' in rendered; assert 'PUT /api/journal-entries' not in rendered; 'AC8.13.53'; 'AC8.13.53'; _m1_methods = ('trace', 'head', 'delete', 'get'); _m1_schema = {'paths': {'/p': {_m1_method: {'tags': ['t']} for _m1_method in _m1_methods}}}; _m1_text = gar.render_openapi_reference(_m1_schema); _m1_rows = [_m1_line.split('`')[1] for _m1_line in _m1_text.splitlines() if '| `/p` |' in _m1_line]; assert _m1_rows == ['GET', 'DELETE', 'HEAD', 'TRACE']; 'AC8.13.53'; 'AC8.13.53'; _m2_text = gar.OUTPUT_PATH.read_text(encoding='utf-8'); assert 'Generated by `python tools/generate_api_reference.py`' in _m2_text; assert '| `POST` | `/reconciliation/runs`' in _m2_text; assert '`ReconciliationRunRequest`' in _m2_text; assert '`account_id` (query)' not in _m2_text; assert '`start_date` (query)' not in _m2_text.split('`/reconciliation/runs`', 1)[1].split('\n', 1)[0]; assert '`PUT` | `/journal-entries/{entry_id}`' not in _m2_text
def test_generate_renders_the_openapi_spec_loader_output(monkeypatch) -> None: 'AC8.13.53'; schema = {'info': {'title': 'Loader Probe'}, 'paths': {}}; monkeypatch.setattr(gen, 'load_openapi', lambda: schema); assert gar.generate() == gar.render_openapi_reference(schema)
def test_main_writes_generated_output(monkeypatch, tmp_path) -> None: 'AC8.13.53'; output = tmp_path / 'nested' / 'api.md'; monkeypatch.setattr(gar, 'generate', lambda: '# API\n'); assert gar.main(['--output', str(output)]) == 0; assert output.read_text(encoding='utf-8') == '# API\n'
def test_main_check_passes_when_output_is_current(monkeypatch, tmp_path) -> None: 'AC8.13.53'; output = tmp_path / 'api.md'; output.write_text('# API\n', encoding='utf-8'); monkeypatch.setattr(gar, 'generate', lambda: '# API\n'); assert gar.main(['--output', str(output), '--check']) == 0
def test_main_check_fails_when_output_is_missing(monkeypatch, tmp_path, capsys) -> None: 'AC8.13.53'; output = tmp_path / 'missing.md'; monkeypatch.setattr(gar, 'generate', lambda: '# API\n'); assert gar.main(['--output', str(output), '--check']) == 1; captured = capsys.readouterr(); assert 'generated API reference is missing' in captured.err
def test_main_check_fails_when_output_is_stale(monkeypatch, tmp_path, capsys) -> None: 'AC8.13.53'; output = tmp_path / 'api.md'; output.write_text('# Old\n', encoding='utf-8'); monkeypatch.setattr(gar, 'generate', lambda: '# New\n'); assert gar.main(['--output', str(output), '--check']) == 1; captured = capsys.readouterr(); assert 'generated API reference is stale' in captured.err; assert '---' in captured.err; assert '+++' in captured.err
